with unpacked as (select id, customer_id, coupon_codes, items, attributes, try_cast(attributes['weight_kg'] as double) as weight_kg, size(items) as num_items from carts where array_contains(coupon_codes, 'BUNDLE')) select customer_id, case when weight_kg >= 3.6 then 'PREMIUM' else 'STANDARD' end as weight_kg_tier, count(distinct customer_id) as distinct_customer_ids, round(avg(weight_kg), 2) as avg_weight_kg, approx_percentile(weight_kg, 0.95) as weight_kg_p95 from unpacked group by customer_id, case when weight_kg >= 3.6 then 'PREMIUM' else 'STANDARD' end
